  if (!text) return [];

  let words = text.split(/ /);
  let lines = [];

  for (let word of words) {
    if (word.length <= width) {
      let line = word;
      while (words.length > 0 && line.length < width) {
        line += ' ' + words.shift();
      }
      lines.push(line);
    } else {
      lines.push(word);
    }
  }

  return lines;
"}

