{"code":"function topoSort(deps) {
  const visited = new Set();
  const stack = new Set();
  const result = [];

  function dfs(node) {
    if (stack.has(node)) {
      throw new Error('Cycle detected');
    }

    if (visited.has(node)) {
      return;
    }

    visited.add(node);
    stack.add(node);

    for (const neighbor of deps[node]) {
      dfs(neighbor);
    }

    stack.delete(node);
    result.push(node);
  }

  for (const node in deps) {
    dfs(node);
  }

  return result.reverse();
"}
